import{i as e}from"./client-HUqx_zHX.js";var t={state:async()=>(await e.get(`/neodesk/api/state`)).data,command:async(t,n=!1)=>(await e.post(`/neodesk/api/execution/`+t,{request_id:crypto.randomUUID(),confirm_live:n})).data,protection:async(t,n)=>(await e.post(`/neodesk/api/position/protection`,{trade_id:t,changes:n})).data,close:async t=>(await e.post(`/neodesk/api/position/close`,{trade_id:t,confirmed:!0,request_id:crypto.randomUUID()})).data,chart:async(t,n)=>(await e.get(`/neodesk/api/chart`,{params:{instrument:t,interval:n}})).data,settings:async t=>(await e.post(`/neodesk/api/settings`,{profile:t})).data};export{t};